function LocationField({ label, value, onChange, placeholder, icon: Icon = MapPin, id }) {
  const [focused, setFocused] = useState(false);
  const suggestions = value ? locations.filter((item) => item.toLowerCase().includes(value.toLowerCase())).slice(0, 4) : locations.slice(0, 4);
  return <div className="relative">
    <label htmlFor={id} className="mb-2 block text-xs font-bold uppercase tracking-[.1em] text-[#74788c]">{label}</label>
    <div className={`flex items-center gap-3 rounded-xl border bg-[#fffaf0] px-3 transition-smooth ${focused ? 'border-[#f7a33b] ring-2 ring-[#f7a33b]/20' : 'border-[#d6d9e2]'}`}>
      <Icon size={18} className={label === 'Pickup point' ? 'text-[#3c897f]' : 'text-[#f7a33b]'} />
      <input id={id} value={value} onChange={(e) => onChange(e.target.value)} onFocus={() => setFocused(true)} onBlur={() => setTimeout(() => setFocused(false), 160)} placeholder={placeholder} className="min-h-12 w-full bg-transparent text-sm font-semibold text-[#252a4b] outline-none placeholder:text-[#a3a6b4]" autoComplete="off" data-testid={`input-${id}`} />
    </div>
    {focused && <div className="absolute left-0 right-0 top-[76px] z-20 overflow-hidden rounded-xl border border-[#dfe1e8] bg-[#fffaf0] p-1 shadow-float">
      {suggestions.map((item) => <button type="button" key={item} onMouseDown={() => onChange(item)} className="flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-sm font-medium text-[#454963] hover:bg-[#eef0f6]" data-testid={`suggestion-${item.replaceAll(' ', '-').toLowerCase()}`}><MapPin size={15} className="text-[#7a7e91]" />{item}</button>)}
      {!suggestions.length && <p className="p-3 text-sm text-[#74788c]">No Bihar location found yet.</p>}
    </div>}
  </div>;
}

function BookingWidget({ compact = false }) {
  const [, setLocation] = useLocation();
  const [tab, setTab] = useState('local');
  const [pickup, setPickup] = useState('');
  const [destination, setDestination] = useState('');
  const [date, setDate] = useState('Today');
  const [passengers, setPassengers] = useState('1');
  const [error, setError] = useState('');
  const submit = (e) => {
    e.preventDefault();
    if (!pickup.trim() || !destination.trim()) { setError('Add both a pickup and destination to see your ride options.'); return; }
    if (pickup.trim().toLowerCase() === destination.trim().toLowerCase()) { setError('Pickup and destination need to be different places.'); return; }
    setLocation(`/book?pickup=${encodeURIComponent(pickup)}&destination=${encodeURIComponent(destination)}&trip=${tab}`);
  };
  return <form onSubmit={submit} className={`relative rounded-2xl border border-[#dedfe5] bg-[#fffaf0] p-4 shadow-float ${compact ? '' : 'sm:p-6'}`} data-testid="form-booking-widget">
    <div className="mb-5 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.12em] text-[#3c897f]">Start here</p><h2 className="mt-1 font-display text-xl font-bold text-[#252a4b]">Where are you headed?</h2></div><div className="rounded-full bg-[#eef0f6] p-2 text-[#252a4b]"><Navigation size={18} /></div></div>
    <div className="mb-5 grid grid-cols-3 rounded-xl bg-[#eef0f6] p-1">
      {[['local', 'Local'], ['outstation', 'Outstation'], ['airport', 'Airport']].map(([value, label]) => <button type="button" key={value} onClick={() => setTab(value)} className={`rounded-lg py-2.5 text-xs font-bold transition-smooth ${tab === value ? 'bg-[#252a4b] text-[#fffaf0] shadow-sm' : 'text-[#74788c] hover:text-[#252a4b]'}`} data-testid={`button-trip-${value}`}>{label}</button>)}
    </div>
    <div className="space-y-4"><LocationField id="pickup" label="Pickup point" value={pickup} onChange={setPickup} placeholder="Search a Bihar landmark" /><LocationField id="destination" label="Going to" value={destination} onChange={setDestination} placeholder="Where should we drop you?" icon={MapPin} /></div>
    {!compact && <div className="mt-4 grid gap-3 sm:grid-cols-2"><div><label htmlFor="date" className="mb-2 block text-xs font-bold uppercase tracking-[.1em] text-[#74788c]">When</label><div className="flex items-center gap-2 rounded-xl border border-[#d6d9e2] px-3"><CalendarDays size={16} className="text-[#3c897f]" /><select id="date" value={date} onChange={(e) => setDate(e.target.value)} className="min-h-11 w-full bg-transparent text-sm font-semibold outline-none" data-testid="select-date"><option>Today</option><option>Tomorrow</option><option>Choose a date</option></select></div></div><div><label htmlFor="passengers" className="mb-2 block text-xs font-bold uppercase tracking-[.1em] text-[#74788c]">Passengers</label><div className="flex items-center gap-2 rounded-xl border border-[#d6d9e2] px-3"><Users size={16} className="text-[#3c897f]" /><select id="passengers" value={passengers} onChange={(e) => setPassengers(e.target.value)} className="min-h-11 w-full bg-transparent text-sm font-semibold outline-none" data-testid="select-passengers"><option value="1">1 passenger</option><option value="2">2 passengers</option><option value="3">3 passengers</option><option value="4">4 passengers</option><option value="5">5+ passengers</option></select></div></div></div>}
    {error && <p className="mt-3 flex items-center gap-2 text-sm font-semibold text-[#b94736]" role="alert" data-testid="status-booking-error"><AlertCircle size={16} />{error}</p>}
    <Button type="submit" className="mt-5 w-full" data-testid="button-see-rides">See available rides <ArrowRight size={17} /></Button>
    <p className="mt-3 text-center text-xs text-[#898c9a]"><Lock size={12} className="mr-1 inline" /> No payment until you confirm</p>
  </form>;
}

